import dataJson from "./data.json"

/**
 * One unified kaomoji record, generated by scripts/generate-data.mjs from the
 * `kaomoji-collection` and `emoticon` npm packages. Optional fields are omitted
 * by the generator when empty to keep the bundled JSON small.
 */
export interface KaomojiEntry {
  text: string
  sources: Array<"kaomoji" | "emoticon">
  category: string
  name?: string
  description?: string
  tags: string[]
  emoji?: string
}

// The generator omits empty fields to save space; normalize tags back to an
// array so search/preview code can rely on it always being present.
export const entries: KaomojiEntry[] = (dataJson as Array<Partial<KaomojiEntry> & { text: string }>).map(raw => ({
  ...raw,
  tags: raw.tags ?? []
})) as KaomojiEntry[]

const byText = new Map<string, KaomojiEntry>()
for (const entry of entries) {
  byText.set(entry.text, entry)
}

export function findByText(text: string): KaomojiEntry | undefined {
  return byText.get(text)
}

export function entryCount(): number {
  return entries.length
}

interface IndexedEntry {
  entry: KaomojiEntry
  text: string
  category: string
  name: string
  description: string
  tags: string[]
  sources: string[]
}

let index: IndexedEntry[] | undefined

/** Build the lowercase search index once; query() calls this lazily too. */
export function buildIndex(): void {
  if (index) {
    return
  }
  index = entries.map(entry => ({
    entry,
    text: entry.text.toLowerCase(),
    category: entry.category.toLowerCase(),
    name: (entry.name ?? "").toLowerCase(),
    description: (entry.description ?? "").toLowerCase(),
    tags: entry.tags.map(tag => tag.toLowerCase()),
    sources: entry.sources.map(source => source.toLowerCase())
  }))
}

/**
 * Score one entry against an already-lowercased query. 0 means no match.
 * Tiers: text exact > text prefix > category exact > name/description hit >
 * category substring > tags hit > text substring.
 */
export function scoreEntry(item: IndexedEntry, q: string): number {
  if (item.text === q) {
    return 100
  }
  if (item.text.startsWith(q)) {
    return 90
  }
  if (item.category === q) {
    return 80
  }
  if (item.name.includes(q)) {
    return 70
  }
  if (item.category.includes(q)) {
    return 65
  }
  if (item.tags.some(tag => tag.includes(q))) {
    return 60
  }
  if (item.description.includes(q)) {
    return 55
  }
  if (item.text.includes(q)) {
    return 50
  }
  return 0
}

const MAX_QUERY_TOKENS = 8

type QueryField = "text" | "tag" | "cat" | "src"

interface QueryToken {
  field?: QueryField
  value: string
}

const FIELD_ALIASES: Record<string, QueryField> = {
  text: "text",
  tag: "tag",
  tags: "tag",
  cat: "cat",
  category: "cat",
  src: "src",
  source: "src",
  sources: "src"
}

/**
 * Parse a query into whitespace-separated tokens. A `field:value` token whose
 * prefix is a known alias and whose value is non-empty becomes a field filter;
 * everything else stays a plain token, so literal kaomoji keep working.
 * Duplicates are dropped and the count is capped so a pathological query
 * cannot turn one keystroke into thousands of substring scans. `\s` also
 * matches the ideographic space (U+3000) commonly produced by CJK IMEs.
 */
export function parseQuery(q: string): QueryToken[] {
  const seen = new Set<string>()
  const tokens: QueryToken[] = []
  for (const raw of q.trim().toLowerCase().split(/\s+/)) {
    if (!raw) {
      continue
    }
    const colon = raw.indexOf(":")
    const field = colon > 0 ? FIELD_ALIASES[raw.slice(0, colon)] : undefined
    const token: QueryToken = field && colon < raw.length - 1 ? { field, value: raw.slice(colon + 1) } : { value: raw }
    const key = `${token.field ?? "*"}:${token.value}`
    if (seen.has(key)) {
      continue
    }
    seen.add(key)
    tokens.push(token)
    if (tokens.length >= MAX_QUERY_TOKENS) {
      break
    }
  }
  return tokens
}

function scoreTextValue(text: string, value: string): number {
  if (text === value) {
    return 100
  }
  if (text.startsWith(value)) {
    return 90
  }
  if (text.includes(value)) {
    return 50
  }
  return 0
}

function scoreTagValues(tags: string[], value: string): number {
  let best = 0
  for (const tag of tags) {
    if (tag === value) {
      return 75
    }
    if (tag.startsWith(value)) {
      best = Math.max(best, 70)
    } else if (tag.includes(value)) {
      best = Math.max(best, 60)
    }
  }
  return best
}

function scoreCategoryValue(category: string, value: string): number {
  if (category === value) {
    return 80
  }
  if (category.startsWith(value)) {
    return 75
  }
  if (category.includes(value)) {
    return 65
  }
  return 0
}

function scoreSourceValues(sources: string[], value: string): number {
  let best = 0
  for (const source of sources) {
    if (source === value) {
      return 85
    }
    if (source.startsWith(value)) {
      best = Math.max(best, 82)
    }
  }
  return best
}

/** Score one parsed token; field filters only look at their own field. */
function scoreToken(item: IndexedEntry, token: QueryToken): number {
  if (token.field === "text") {
    return scoreTextValue(item.text, token.value)
  }
  if (token.field === "tag") {
    return scoreTagValues(item.tags, token.value)
  }
  if (token.field === "cat") {
    return scoreCategoryValue(item.category, token.value)
  }
  if (token.field === "src") {
    return scoreSourceValues(item.sources, token.value)
  }
  return scoreEntry(item, token.value)
}

/**
 * Score a multi-token query: every token must match (AND), and tokens found
 * in the kaomoji text itself count more than metadata-only hits. Field filters
 * are scored by scoreToken so `tag:` never accidentally matches the text.
 */
function scoreCombined(item: IndexedEntry, tokens: QueryToken[]): number {
  let sum = 0
  let textHits = 0
  let plain = true
  for (const token of tokens) {
    const score = scoreToken(item, token)
    if (score === 0) {
      return 0
    }
    sum += score
    if (token.field) {
      plain = false
    }
    if ((!token.field || token.field === "text") && item.text.includes(token.value)) {
      textHits++
    }
  }
  const base = sum / tokens.length
  const coverage = (textHits / tokens.length) * 30
  // Reward the literal phrase too, so pasting a kaomoji that contains spaces
  // still ranks the exact record first even though the query was split. Field
  // filters intentionally skip this bonus: their values are not one phrase.
  const phrase = plain && tokens.length > 1 && item.text.includes(tokens.map(token => token.value).join(" ")) ? 30 : 0
  return Math.round(base + coverage + phrase)
}

/**
 * Case-insensitive search over text/category/name/description/tags/sources.
 * Whitespace-separated tokens are combined with AND: "love ^" means the
 * record carries "love" somewhere and a caret in its text. Tokens may be
 * narrowed with `text:`, `tag:`, `cat:` and `src:` filters.
 */
export function searchKaomoji(queryText: string, limit = 100): KaomojiEntry[] {
  buildIndex()
  const tokens = parseQuery(queryText)
  if (tokens.length === 0) {
    return []
  }
  const scored: Array<{ entry: KaomojiEntry; score: number }> = []
  for (const item of index as IndexedEntry[]) {
    const score = tokens.length === 1 ? scoreToken(item, tokens[0]) : scoreCombined(item, tokens)
    if (score > 0) {
      scored.push({ entry: item.entry, score })
    }
  }
  scored.sort((a, b) => b.score - a.score || a.entry.text.length - b.entry.text.length)
  return scored.slice(0, limit).map(s => s.entry)
}

/** Random sample for browsing on an empty query (Fisher-Yates on a copy). */
export function sampleKaomoji(count = 60, random: () => number = Math.random): KaomojiEntry[] {
  const pool = entries.slice()
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1))
    const tmp = pool[i]
    pool[i] = pool[j]
    pool[j] = tmp
  }
  return pool.slice(0, count)
}

/**
 * SubTitle mapping: emoticon records carry a name, kaomoji records
 * only have a category. Dual-source records prefer the emoticon form.
 */
export function subtitleFor(entry: KaomojiEntry): string {
  return entry.name || entry.category
}

/** Tags to show in the preview beyond source and category (deduped, capped). */
export function extraTags(entry: KaomojiEntry, cap = 8): string[] {
  const seen = new Set<string>([entry.category.toLowerCase()])
  const out: string[] = []
  for (const tag of entry.tags) {
    const key = tag.toLowerCase()
    if (seen.has(key)) {
      continue
    }
    seen.add(key)
    out.push(tag)
    if (out.length >= cap) {
      break
    }
  }
  return out
}

/** Short stable hash of a text, used to keep action/result ids unique. */
export function textHash(text: string): string {
  let hash = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i)
    hash = Math.imul(hash, 0x01000193)
  }
  return (hash >>> 0).toString(16)
}
